create extension if not exists pgcrypto;
create table if not exists public.challenges(id uuid primary key default gen_random_uuid(),name text not null,start_date date not null,end_date date not null,starting_balance numeric not null check(starting_balance>=0),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.contestants(id uuid primary key default gen_random_uuid(),name text not null,broker text not null,starting_balance numeric not null check(starting_balance>=0),current_balance numeric not null check(current_balance>=0),status text not null default 'Active' check(status in('Active','Completed','Eliminated')),created_at timestamptz not null default now());
create table if not exists public.balance_history(id bigint generated always as identity primary key,contestant_id uuid not null references public.contestants(id) on delete cascade,balance numeric not null check(balance>=0),recorded_on date not null default current_date,created_at timestamptz not null default now());
create table if not exists public.content_items(id uuid primary key default gen_random_uuid(),type text not null check(type in('Lesson','Result','Activity')),title text not null,description text not null,file_url text,created_at timestamptz not null default now());
alter table public.challenges enable row level security;alter table public.contestants enable row level security;alter table public.balance_history enable row level security;alter table public.content_items enable row level security;
create policy "read challenges" on public.challenges for select using(true);create policy "read contestants" on public.contestants for select using(true);create policy "read history" on public.balance_history for select using(true);create policy "read content" on public.content_items for select using(true);
create policy "admin challenges" on public.challenges for all to authenticated using((auth.jwt()->>'email')='marcneizha@gmail.com') with check((auth.jwt()->>'email')='marcneizha@gmail.com');create policy "admin contestants" on public.contestants for all to authenticated using((auth.jwt()->>'email')='marcneizha@gmail.com') with check((auth.jwt()->>'email')='marcneizha@gmail.com');create policy "admin history" on public.balance_history for all to authenticated using((auth.jwt()->>'email')='marcneizha@gmail.com') with check((auth.jwt()->>'email')='marcneizha@gmail.com');create policy "admin content" on public.content_items for all to authenticated using((auth.jwt()->>'email')='marcneizha@gmail.com') with check((auth.jwt()->>'email')='marcneizha@gmail.com');
